def safeWithinKMoves(graph, k):
    n = len(graph)
    rev = [[] for _ in range(n)]
    remaining = [len(graph[i]) for i in range(n)]
    for i in range(n):
        for j in graph[i]:
            rev[j].append(i)
    depth = [0] * n
    stack = [i for i in range(n) if remaining[i] == 0]
    while stack:
        j = stack.pop()
        for i in rev[j]:
            if depth[j] + 1 > depth[i]:
                depth[i] = depth[j] + 1
            remaining[i] -= 1
            if remaining[i] == 0:
                stack.append(i)
    return [i for i in range(n) if remaining[i] == 0 and depth[i] <= k]
